    "createdAt": "2026-08-05T19:33:03.664Z",
    "date": "2026-08-05",
    "description": "Solicito a realização dos serviços de manutenção e adequação na sala destinada ao armazenamento de armamentos desta unidade prisional, visando atender às normas de segurança, organização e preservação dos materiais.\n\nPara tanto, faz-se necessária a execução dos seguintes serviços:\n\n* Construção de alvenaria para adequação do ambiente;\n* Construção de caixa de contenção;\n* Confecção e instalação de armário com gavetas individuais;\n* Pintura do piso da sala;\n* Instalação de cofre destinado ao armazenamento de armas particulares dos Policiais Penais.",
    "id": "-OzIPYoD28XHCCwMIWT4",
    "inspectionObservations": "MANUTENÇÃO REALIZADA PELO POLICIAL PENAL DANILO RIBEIRO COPPI, UTILIZANDO A MÃO DE OBRA DE 02 PPL`S, PINTORES, DO SETOR MANUTENÇÃO EXTERNA.",
